import io as _triton_eval_io
import os as _triton_eval_os
_triton_eval_files = {'cases.json': '{"n":128}\n{"n":1024}\n', 'EvalServiceMigrationAdd.json': '{"n":128}\n{"n":1024}\n'}

def _triton_eval_open(path, mode='r', *args, **kwargs):
    if mode not in ('r', 'rt', 'rb'):
        raise ValueError('reference sidecars are read-only')
    name = _triton_eval_os.path.basename(path)
    if name not in _triton_eval_files:
        raise FileNotFoundError('reference sidecar was not supplied')
    text = _triton_eval_files[name]
    return _triton_eval_io.BytesIO(text.encode('utf-8')) if 'b' in mode else _triton_eval_io.StringIO(text)
